UNION=[U,['晚期拉丁语：ūniō / ūniōnem','联合；合而为一'],['古法语：union','结合；联合'],['英语：union','联合体；工会；结合']]
UNITY=[U,['拉丁语：ūnitās','合一；统一的状态'],['古法语：unité；中古英语：unite','统一；和谐'],['英语：unity','团结；统一；一体性']]
UNIT=UNITY+[['英语词形调整：unit','作为一个整体看待的单元、单位']]
