UNIVERSE=[U,['拉丁语：ūni- + versus → ūniversus','合在一起 → 全部、整体'],['拉丁语：ūniversum；古法语：univers','一切事物的总和'],['英语：universe','宇宙；所考虑的全部事物']]
UNIVERSAL=UNIVERSE[:2]+[['拉丁语：ūniversālis','涉及全体的'],['古法语：universal','普遍的；全部的'],['英语：universal','普遍适用的；通用的']]
UNIFORM=[U,['拉丁语：ūni- + forma → ūniformis','一个样式 → 形式一致的'],['中古法语：uniforme','一致的'],['英语：uniform','一致的；标准式样的服装']]
